use xiom.io;
module counter {
  type Tally = {
    count: Int;
    max_allowed: Int;
  }

  pub fn create() -> Tally {
    Tally{ count: 0, max_allowed: 999 }
  }

  pub fn increment(c: &mut Tally) -> Bool {
    if c.count >= c.max_allowed {
      return false;
    };
    c.count += 1;
    true
  }

  pub fn get(c: &Tally) -> Int {
    c.count
  }

  pub fn reset(c: &mut Tally) {
    c.count = 0;
  }
}

fn main() -> Int {
  var c = counter.create();
  counter.increment(&mut c);
  counter.increment(&mut c);
  counter.increment(&mut c);
  io.println(counter.get(&c).to_str());
  return 0;
}
